import{_ as a,c as e,o as r,a2 as l}from"./chunks/framework.Ps2l0eYJ.js";const u=JSON.parse('{"title":"FFmpeg 基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"modules/ffmpeg/learn-ffmpeg/src/01_ffmpeg.md","filePath":"modules/ffmpeg/learn-ffmpeg/src/01_ffmpeg.md"}'),t={name:"modules/ffmpeg/learn-ffmpeg/src/01_ffmpeg.md"},i=l('<h1 id="ffmpeg-基础知识" tabindex="-1">FFmpeg 基础知识 <a class="header-anchor" href="#ffmpeg-基础知识" aria-label="Permalink to &quot;FFmpeg 基础知识&quot;">​</a></h1><h4 id="基础术语" tabindex="-1">基础术语 <a class="header-anchor" href="#基础术语" aria-label="Permalink to &quot;基础术语&quot;">​</a></h4><h5 id="容器-container" tabindex="-1">容器(Container) <a class="header-anchor" href="#容器-container" aria-label="Permalink to &quot;容器(Container)&quot;">​</a></h5><p>​ 一种文件格式，比如flv，mkv等。包含下面5种流以及文件头信息。</p><h5 id="流-stream" tabindex="-1">流(Stream) <a class="header-anchor" href="#流-stream" aria-label="Permalink to &quot;流(Stream)&quot;">​</a></h5><p>​ 一种视频数据信息的传输方式，5种流：音频，视频，字幕，附件，数据。</p><h5 id="帧-frame" tabindex="-1">帧(Frame) <a class="header-anchor" href="#帧-frame" aria-label="Permalink to &quot;帧(Frame)&quot;">​</a></h5><p>​ 帧代表一幅静止的图像，分为I帧，P帧，B帧。</p><h5 id="编解码器-codec" tabindex="-1">编解码器(Codec) <a class="header-anchor" href="#编解码器-codec" aria-label="Permalink to &quot;编解码器(Codec)&quot;">​</a></h5><p>​ 是对视频进行压缩或者解压缩，CODEC = COde（编码） +DECode（解码）。</p><h5 id="复用-解复用-mux-demux" tabindex="-1">复用/解复用(mux/demux) <a class="header-anchor" href="#复用-解复用-mux-demux" aria-label="Permalink to &quot;复用/解复用(mux/demux)&quot;">​</a></h5><p>​ 把不同的流按照某种容器的规则放入容器，这种行为叫做复用（mux）。</p><p>​ 把不同的流从某种容器中解析出来，这种行为叫做解复用(demux)。</p><h5 id="帧率" tabindex="-1">帧率 <a class="header-anchor" href="#帧率" aria-label="Permalink to &quot;帧率&quot;">​</a></h5><p>​ 帧率也叫帧频率，帧率是视频文件中每一秒的帧数，肉眼想看到连续移动图像至少需要15帧。</p><h5 id="码率" tabindex="-1">码率 <a class="header-anchor" href="#码率" aria-label="Permalink to &quot;码率&quot;">​</a></h5><p>​ 比特率(也叫码率，数据率)是一个确定整体视频/音频质量的参数，秒为单位处理的字节数，码率和视频质量成正比，在视频文件中中比特率用bps来表达。</p><h4 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h4><p>​ FFmpeg的名称来自MPEG视频编码标准，前面的“FF”代表“Fast Forward”，FFmpeg是一套可以用来记录、转换数字音频、视频，并能将其转化为流的开源计算机程序。可以轻易地实现多种视频格式之间的相互转换。包括如下几个部分：</p><ul><li>libavformat：用于各种音视频封装格式的生成和解析，包括获取解码所需信息以生成解码上下文结构和读取音视频帧等功能，包含demuxers和muxer库。</li><li>libavcodec：用于各种类型声音/图像编解码。</li><li>libavutil：包含一些公共的工具函数。</li><li>libswscale：用于视频场景比例缩放、色彩映射转换。</li><li>libpostproc：用于后期效果处理。</li><li><a href="./B_FFmpeg使用指南.html">ffmpeg</a>：是一个命令行工具，用来对视频文件转换格式，也支持对电视卡实时编码。</li><li>ffsever：是一个HTTP多媒体实时广播流服务器，支持时光平移。</li><li><a href="./A_FFplay使用指南.html">ffplay</a>：是一个简单的播放器，使用ffmpeg 库解析和解码，通过SDL显示。</li><li><a href="./C_FFprobe使用指南.html">ffprobe</a>：收集多媒体文件或流的信息，并以人和机器可读的方式输出。</li></ul><h4 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h4><ul><li><a href="https://wenku.baidu.com/view/296eefcaf90f76c661371af1.html" target="_blank" rel="noreferrer">《FFmpeg基础》</a></li></ul>',22),o=[i];function m(h,f,n,d,c,s){return r(),e("div",null,o)}const _=a(t,[["render",m]]);export{u as __pageData,_ as default};
